package com.bank.rgk.kafka;

import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

// Kafka: async durable log, publish and move on, many consumers, replayable.
public class KafkaBackbone {
    private static final Logger log = Logger.getLogger(KafkaBackbone.class.getName());
    private final List<String> durableLog = new ArrayList<>();
    public void publish(String topic, String event) {
        durableLog.add(event);
        log.info(() -> "Kafka (async log) → '" + topic + "': " + event
                     + " — producer does NOT wait, consumers read later");
    }
    public int offset() { return durableLog.size(); }
}
