package com.bank.rgk.orchestrator;

import com.bank.rgk.grpc.GrpcAccountStub;
import com.bank.rgk.kafka.KafkaBackbone;
import com.bank.rgk.rest.RestEdge;
import java.math.BigDecimal;
import java.util.logging.Logger;

// Uses the RIGHT technology per hop: REST edge, gRPC internal, Kafka fan-out.
public class TransferOrchestrator {
    private static final Logger log = Logger.getLogger(TransferOrchestrator.class.getName());
    private final RestEdge restEdge;
    private final GrpcAccountStub accountStub;
    private final KafkaBackbone kafka;

    public TransferOrchestrator(RestEdge restEdge, GrpcAccountStub accountStub, KafkaBackbone kafka) {
        this.restEdge = restEdge; this.accountStub = accountStub; this.kafka = kafka;
    }

    public String transfer(String from, String to, BigDecimal amount) {
        restEdge.receiveTransfer("{\"from\":\"" + from + "\",\"amount\":" + amount + "}"); // REST
        boolean debited = accountStub.debit(from, amount);                                  // gRPC
        if (!debited) return "FAILED";
        kafka.publish("payment-events", "PAYMENT_COMPLETED from=" + from + " amount=" + amount); // Kafka
        return "COMPLETED";
    }
}
